class Flag:
 def __bool__(self):raise RuntimeError('truth failed')
class C:
 def __enter__(self):return self
 def __exit__(self,*args):return Flag()
try:
 with C():raise ValueError('body')
except RuntimeError as e:print(str(e),type(e.__context__).__name__)
except ValueError:print('body escaped')

class C:
 def __enter__(self):return self
 def __exit__(self,*args):return iter([])
try:
 with C():raise ValueError('body')
except ValueError:print('escaped')
else:print('suppressed')

