events=[]
class Slot:
 def __init__(self,name):self.name=name
 def __get__(self,obj,owner):
  events.append('lookup-'+self.name)
  if self.name=='enter':return lambda:events.append('enter')
  return lambda *args:events.append('exit')
class C:__enter__=Slot('enter');__exit__=Slot('exit')
with C():events.append('body')
print(events)

