import sys
class C:
 def __enter__(self):return self
 def __exit__(self,t,e,tb):
  print(sys.exc_info()[1] is e)
  try:raise
  except ValueError as caught:print(caught is e)
  return True
with C():raise ValueError('body')
print(sys.exc_info()[1] is None)

